INSERT INTO `hero_slides` VALUES (1,'home','slider','EDITORIAL CONTENT & COPYWRITING STUDIO','Words That Work. Stories That Sell.','We turn research, ideas and brand thinking into content people remember — and businesses can grow with.','/uploads/hero/wdr_6a884518c6fb56.72010770.png','','Explore Our Work','services.php','Start a Conversation','contact.php',1,1,'2026-08-22 20:53:38','2026-08-24 06:16:26'),(2,'home','slider','STRATEGIC BRAND ARCHITECTURE','Bespoke Copy for Ambitious Brands.','From pitch-perfect taglines to deep-dive technical whitepapers, our words give your brand the authority it deserves.','/uploads/hero/wdr_6a88450ca75872.28926131.png','','See What We Do','services.php','Start a Conversation','contact.php',2,1,'2026-08-22 20:53:38','2026-08-22 21:31:08'),(3,'home','slider','CONVERSION & SEO EXCELLENCE','Content Designed to Rank, Read, and Convert.','We build structured topic clusters, high-intent landing copy, and thought leadership articles that drive measurable pipeline revenue.','/uploads/hero/wdr_6a88452ddf02f0.09972969.png','','View Case Studies','services.php','Get in Touch','contact.php',3,1,'2026-08-22 20:53:38','2026-08-22 21:31:41'),(4,'who_we_are','slider','EDITORIAL BRAND STORY & STUDIO MANIFESTO','Who We Are','A team of writers, strategists, and editors driven by the belief that great words build great brands.','/uploads/hero/wdr_6a8d4b6822fb92.17670216.png','','Explore Our Story','#our-mission','Start a Conversation','contact.php',1,1,'2026-08-24 05:40:38','2026-08-25 02:29:36'),(7,'services','slider','EDITORIAL CONTENT & COPYWRITING CAPABILITIES','Content with a Job to Do.','Keyword-rich SEO articles, high-converting copy, developer documentation, and executive ghostwriting designed to drive pipeline.','/uploads/hero/wdr_6a8d4b80cd25d5.15747678.png','','Explore Services','#services-grid','Start a Conversation','contact.php',1,1,'2026-08-24 05:40:38','2026-08-25 02:30:00'),(9,'contact','','START A CONVERSATION','Let’s Build Words That Work.','Tell us about your project, timeline, and goals. We’ll get back to you within 24 hours with strategic clarity.','/uploads/contact/wdr_6a8d4d73762917.44393604.png','','','','','',1,1,'2026-08-24 05:40:38','2026-08-25 02:38:19'),(10,'blog','','THE EDITORIAL JOURNAL','Frameworks, Strategies & Insights.','Deep-dive analyses on search intent, conversion copywriting, developer documentation, and brand voice architecture.','/uploads/blog/wdr_6a8d4b97758883.14263586.png','','','','','',1,1,'2026-08-24 05:40:38','2026-08-25 02:30:23'),(11,'case_studies','','VERIFIED COMMERCIAL PROOF • CASE STUDIES','Real Words. Measured in Revenue & Pipeline.','Explore how fast-growth startups, enterprise SaaS platforms, and global advisory firms partner with WORDORA to scale search authority and conversion velocity.','/uploads/case-studies/wdr_6a8d4babe748c1.06544049.png',NULL,'','','','',1,1,'2026-08-24 08:13:06','2026-08-25 02:30:43');
