INSERT INTO `services` VALUES (1,'SEO Content Writing','ri-search-eye-line','Keyword-rich, search-intent content architectures and high-ranking articles engineered to dominate Google page one and convert organic traffic into recurring revenue.','[{\"icon\":\"ri-quill-pen-line\",\"title\":\"SEO Blog Writing\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-file-text-line\",\"title\":\"SEO Articles\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-layout-masonry-line\",\"title\":\"Website Content\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-search-eye-line\",\"title\":\"Landing Page Content\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-focus-3-line\",\"title\":\"Product & Service Pages\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-sparkling-fill\",\"title\":\"Keyword-Optimized Content\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-shield-star-line\",\"title\":\"Content Refresh & Optimization\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-compass-3-line\",\"title\":\"Long-Form SEO Content\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"}]','img/Blog service.png','Keyword cluster architecture, 2,500+ word pillar articles, schema markup, search intent mapping','4.2x','Organic Search Traffic Lift','Search & Organic Growth','Search-Dominant Content That Turns Traffic into Pipeline','Topic cluster architecture, search-intent optimization, and rigorous long-form guides engineered to capture page-one rankings and convert high-intent buyers.','/uploads/services/wdr_6a8d7754caab78.24054062.png','We don’t write generic keyword-stuffed articles. We engineer search-dominant content assets that establish category leadership.','[{\"title\":\"Compound Organic Traffic\",\"desc\":\"Build high-authority topic clusters that generate qualified inbound leads 24\\/7 without recurring ad spend.\",\"icon\":\"ri-line-chart-line\"},{\"title\":\"Google Helpful Content Proof\",\"desc\":\"100% human-researched and cited. Immune to algorithmic updates and AI content penalties.\",\"icon\":\"ri-shield-check-line\"},{\"title\":\"Pipeline Conversion Focus\",\"desc\":\"Every article includes strategic internal links, CTA placements, and conversion pathways tailored to your sales funnel.\",\"icon\":\"ri-funds-box-line\"}]','[{\"role\":\"B2B SaaS Companies\",\"desc\":\"Scaling organic product demo requests and outranking entrenched enterprise competitors.\"},{\"role\":\"E-Commerce Brands\",\"desc\":\"Dominating high-intent transactional search terms and category buying guides.\"},{\"role\":\"Growth Startups\",\"desc\":\"Establishing category authority and lowering customer acquisition costs from day one.\"},{\"role\":\"Digital Marketing Agencies\",\"desc\":\"White-label editorial support that delivers verified search ranking improvements for clients.\"}]','[{\"num\":\"01\",\"title\":\"Search Intent Audit\",\"desc\":\"Competitor keyword gap analysis and search intent mapping before drafting.\"},{\"num\":\"02\",\"title\":\"Topic Cluster Blueprint\",\"desc\":\"Structuring pillar guides, supporting clusters, and schema metadata.\"},{\"num\":\"03\",\"title\":\"Editorial Craftsmanship\",\"desc\":\"Senior writers draft in-depth, authoritative guides with zero AI fluff.\"},{\"num\":\"04\",\"title\":\"On-Page Optimization\",\"desc\":\"Meta tags, internal linking anchors, and conversion call-to-actions.\"}]','[{\"q\":\"How do you choose target keywords for our articles?\",\"a\":\"We conduct extensive competitor keyword gap analyses and search intent audits using enterprise SEO tooling, identifying high-intent commercial terms your buyers are actively searching for.\"},{\"q\":\"Are all SEO articles 100% written by humans?\",\"a\":\"Yes, unconditionally. Every article is written by experienced domain writers, rigorously fact-checked, and polished by managing editors. We never use generative AI filler.\"},{\"q\":\"Do you include on-page SEO, meta schemas, and formatting?\",\"a\":\"Yes. Every deliverable includes optimized title tags, meta descriptions, header structure (H1\\/H2\\/H3), schema suggestions, and internal linking schematics ready for CMS publishing.\"},{\"q\":\"What is the typical turnaround time for an SEO article?\",\"a\":\"Standard long-form articles (1,500 \\u2013 2,500 words) are delivered within 5 to 7 business days, including full research and editorial review.\"},{\"q\":\"How many revisions are included in the scope?\",\"a\":\"Every project includes two full rounds of editorial revisions within 14 days of delivery to ensure complete alignment with your vision.\"}]','Ready to elevate your seo content writing?','Tell us about your brand, goals, and upcoming requirements. We\'ll deliver a tailored proposal within 24 hours.','Start a Conversation','contact.php?service=SEO+Content+Writing','seo-content-writing',1,1),(2,'Social Media Content','ri-instagram-line','Scroll-stopping captions, high-converting social campaigns, and strategic content calendars crafted to capture attention and build an engaged audience across all channels.','[{\"icon\":\"ri-quill-pen-line\",\"title\":\"Instagram Captions\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-file-text-line\",\"title\":\"LinkedIn Posts\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-layout-masonry-line\",\"title\":\"Facebook Content\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-search-eye-line\",\"title\":\"Twitter\\/X Posts\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-focus-3-line\",\"title\":\"Social Media Campaigns\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-sparkling-fill\",\"title\":\"Content Calendars\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-shield-star-line\",\"title\":\"Carousel Copy\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-compass-3-line\",\"title\":\"Short-Form Social Content\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"}]','img/social media service.png','Monthly social calendar, multi-slide carousels, campaign hooks, brand hashtag frameworks','+380%','Social Engagement Rate','Social Engagement & Virality','Scroll-Stopping Social Copy Built for Community & Conversion','Captions, multi-slide carousels, and high-converting campaign copy structured to capture attention, drive viral engagement, and build loyal brand followings.','/uploads/services/wdr_6a8d7761abc6b9.35168196.png','Social feeds move fast. We craft sharp, compelling copy that stops the thumb and sparks genuine conversations.','[{\"title\":\"High-Retention Hooks\",\"desc\":\"First-line hooks and visual narrative framing designed to maximize algorithmic reach and dwell time.\",\"icon\":\"ri-flashlight-line\"},{\"title\":\"Consistent Brand Voice\",\"desc\":\"Unified brand personality across all platforms so your audience immediately recognizes your stature.\",\"icon\":\"ri-sparkling-fill\"},{\"title\":\"Community to Pipeline\",\"desc\":\"Transform passive social followers into active subscribers, event attendees, and product customers.\",\"icon\":\"ri-user-star-line\"}]','[{\"role\":\"Direct-to-Consumer Brands\",\"desc\":\"Building viral product hype, user-generated momentum, and repeat customer loyalty.\"},{\"role\":\"B2B Founders & Execs\",\"desc\":\"Scaling LinkedIn engagement, sharing company milestones, and attracting talent.\"},{\"role\":\"Creator & Media Brands\",\"desc\":\"Maintaining high-velocity posting schedules with pristine editorial craft.\"},{\"role\":\"Marketing Teams\",\"desc\":\"Freeing internal bandwidth by outsourcing monthly social copy calendars.\"}]','[{\"num\":\"01\",\"title\":\"Audience Persona Deconstruction\",\"desc\":\"Auditing past top performers, competitor hooks, and channel demographics.\"},{\"num\":\"02\",\"title\":\"Monthly Content Calendar\",\"desc\":\"Structuring weekly themes, multi-slide carousels, and launch sequences.\"},{\"num\":\"03\",\"title\":\"Copy & Hook Engineering\",\"desc\":\"Crafting scroll-stopping first-line hooks, slide narratives, and link CTAs.\"},{\"num\":\"04\",\"title\":\"Hashtag & Engagement Pack\",\"desc\":\"Delivering platform-optimized tag sets and pinned comment prompts.\"}]','[{\"q\":\"Which social media platforms do you write copy for?\",\"a\":\"We create tailored content for LinkedIn, Instagram, X (Twitter), Facebook, Threads, and YouTube Community posts.\"},{\"q\":\"Do you provide visual design or just copy?\",\"a\":\"We deliver complete copy decks including slide-by-slide carousel scripts, visual design prompts, and headline hierarchies ready for your design team.\"},{\"q\":\"How far in advance do you deliver monthly content calendars?\",\"a\":\"Monthly calendars are delivered 7 to 10 days before the start of the month, allowing ample time for review and scheduling.\"},{\"q\":\"Can you adapt to our brand\\u2019s unique humor and voice?\",\"a\":\"Absolutely. We review your past top-performing posts and brand guidelines to mirror your voice seamlessly.\"},{\"q\":\"Do you include hashtag strategy and call-to-actions?\",\"a\":\"Yes. Every post includes platform-optimized hashtag clusters and engagement-driven closing questions or link CTAs.\"}]','Ready to elevate your social media content?','Tell us about your brand, goals, and upcoming requirements. We\'ll deliver a tailored proposal within 24 hours.','Start a Conversation','contact.php?service=Social+Media+Content','social-media-content',2,1),(3,'Technical Writing','ri-file-code-line','Developer documentation, API reference guides, SDK quickstarts, and enterprise cloud whitepapers that translate complex software architectures into crystal-clear instructions.','[{\"icon\":\"ri-quill-pen-line\",\"title\":\"Developer Documentation\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-file-text-line\",\"title\":\"API Documentation\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-layout-masonry-line\",\"title\":\"User Guides\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-search-eye-line\",\"title\":\"Product Documentation\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-focus-3-line\",\"title\":\"Technical Articles\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-sparkling-fill\",\"title\":\"Knowledge Base Content\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-shield-star-line\",\"title\":\"Tutorials & How-To Guides\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-compass-3-line\",\"title\":\"Whitepapers\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"}]','img/service treasure.png','Interactive OpenAPI suites, markdown repo docs, dev quickstarts, enterprise architectural blueprints','68%','Faster Developer Onboarding','Engineering & Documentation','Complex Architectures Explained with Crystal Clarity','Developer documentation, OpenAPI references, SDK tutorials, and cloud architecture whitepapers that eliminate friction and speed up engineering adoption.','/uploads/services/wdr_6a8d776ae05f97.37958792.png','Engineers value precision. We bridge the gap between complex software systems and intuitive developer documentation.','[{\"title\":\"Accelerate Time-to-Hello-World\",\"desc\":\"Reduce developer drop-off with frictionless quickstarts, verified code samples, and clear SDK guides.\",\"icon\":\"ri-code-s-slash-line\"},{\"title\":\"Deflect Support Tickets\",\"desc\":\"Comprehensive knowledge bases and troubleshooting guides that save engineering hours.\",\"icon\":\"ri-customer-service-2-line\"},{\"title\":\"Win Enterprise RFPs\",\"desc\":\"Authoritative architecture whitepapers and security overviews that satisfy enterprise compliance teams.\",\"icon\":\"ri-shield-keyhole-line\"}]','[{\"role\":\"API-First SaaS Platforms\",\"desc\":\"Empowering external developers to integrate with your REST, GraphQL, or gRPC APIs seamlessly.\"},{\"role\":\"DevTool & Infrastructure Startups\",\"desc\":\"Translating cutting-edge cloud infrastructure into clear setup and CLI tutorials.\"},{\"role\":\"Enterprise IT Providers\",\"desc\":\"Authoring technical whitepapers, migration guides, and compliance documentation.\"},{\"role\":\"Product Teams\",\"desc\":\"Creating end-user knowledge bases, onboarding walkthrus, and feature release notes.\"}]','[{\"num\":\"01\",\"title\":\"Technical Architecture Audit\",\"desc\":\"Dissecting APIs, repos, SDKs, and engineering specifications with dev teams.\"},{\"num\":\"02\",\"title\":\"Information Architecture Schema\",\"desc\":\"Mapping navigation hierarchy, endpoint reference, and quickstart paths.\"},{\"num\":\"03\",\"title\":\"Code Verification & Drafting\",\"desc\":\"Executing code snippets in sandboxes and authoring clean markdown documentation.\"},{\"num\":\"04\",\"title\":\"Peer Review & Delivery\",\"desc\":\"Engineering review, technical copy editing, and Git pull request submission.\"}]','[{\"q\":\"Can your writers work directly in Markdown and Git repositories?\",\"a\":\"Yes. We frequently submit pull requests directly to Git repositories (GitHub, GitLab) formatted for Docusaurus, Mintlify, GitBook, or MkDocs.\"},{\"q\":\"Do you test code samples before publishing?\",\"a\":\"Yes. All SDK snippets, API endpoints, and configuration files are executed and verified in test sandbox environments.\"},{\"q\":\"Can you help restructure an existing messy documentation suite?\",\"a\":\"Absolutely. We perform full information architecture audits, reorganizing topics into intuitive mental models for developers.\"},{\"q\":\"Do you sign NDAs before accessing pre-release software?\",\"a\":\"Yes, unconditionally. We protect all proprietary codebases, roadmaps, and architecture blueprints under strict mutual NDAs.\"},{\"q\":\"What languages and frameworks do your writers understand?\",\"a\":\"We cover Python, JavaScript\\/TypeScript, Go, Rust, Java, PHP, Docker, Kubernetes, AWS, GCP, and modern microservice architectures.\"}]','Ready to elevate your technical writing?','Tell us about your brand, goals, and upcoming requirements. We\'ll deliver a tailored proposal within 24 hours.','Start a Conversation','contact.php?service=Technical+Writing','technical-writing',3,1),(4,'Brand Copywriting','ri-pen-nib-line','Taglines, manifestos, website hero copy, and strategic messaging frameworks that carve out undeniable market stature and turn casual visitors into loyal brand champions.','[{\"icon\":\"ri-quill-pen-line\",\"title\":\"Taglines & Punchlines\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-file-text-line\",\"title\":\"Brand Messaging\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-layout-masonry-line\",\"title\":\"Website Copy\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-search-eye-line\",\"title\":\"Brand Voice\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-focus-3-line\",\"title\":\"About Us Content\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-sparkling-fill\",\"title\":\"Campaign Copy\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-shield-star-line\",\"title\":\"Product Messaging\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"},{\"icon\":\"ri-compass-3-line\",\"title\":\"Marketing Copy\",\"desc\":\"Deeply researched, drafted to institutional standards, and fully aligned with your audience expectations.\",\"badge\":\"VERIFIED SCOPE\"}]','img/brand content.png','Comprehensive Brand Voice Bible, Homepage copy deck, Tagline matrix, Launch messaging sequence','+34%','Conversion Rate Uplift','Voice & Brand Positioning','Words That Define Categories and Command Market Stature','Brand voice bibles, high-converting homepage copy, taglines, and campaign messaging that forge an emotional connection and separate you from competitors.','/uploads/services/wdr_6a8d777b5f4404.58976770.png','Great products fail when they speak with a generic voice. We craft unforgettable brand copy that commands respect.','[{\"title\":\"Unmistakable Positioning\",\"desc\":\"Own a distinct category narrative that competitors cannot easily copy or dilute.\",\"icon\":\"ri-trophy-line\"},{\"title\":\"Conversion Rate Uplift\",\"desc\":\"Clear value propositions that immediately answer \\\"Why you?\\\" within 5 seconds of landing.\",\"icon\":\"ri-percent-line\"},{\"title\":\"Brand Loyalty & Trust\",\"desc\":\"Consistent voice governance across marketing, sales decks, and customer communications.\",\"icon\":\"ri-heart-3-line\"}]','[{\"role\":\"Rebranding Companies\",\"desc\":\"Modernizing stale messaging to reflect market leadership and enterprise maturity.\"},{\"role\":\"Early-Stage Founders\",\"desc\":\"Defining the initial brand manifesto, mission statement, and elevator pitch for launch.\"},{\"role\":\"Consumer & Luxury Brands\",\"desc\":\"Crafting evocative packaging copy, campaign taglines, and manifesto stories.\"},{\"role\":\"Creative Agencies\",\"desc\":\"Partnering on full-scale brand identity and messaging deck overhauls.\"}]','[{\"num\":\"01\",\"title\":\"Founder Discovery Interview\",\"desc\":\"Extracting origins, core differentiators, customer psychology, and vision.\"},{\"num\":\"02\",\"title\":\"Tone Spectrum Matrix\",\"desc\":\"Defining voice parameters, vocabulary rules, taglines, and copy Dos & Don’ts.\"},{\"num\":\"03\",\"title\":\"Copy Deck Drafting\",\"desc\":\"Authoring Homepage, core product pages, manifestos, and pitch deck narratives.\"},{\"num\":\"04\",\"title\":\"Executive Presentation\",\"desc\":\"Presenting brand voice bibles with revision sprints to ensure absolute resonance.\"}]','[{\"q\":\"What does a Brand Voice Bible include?\",\"a\":\"It includes your brand manifesto, core value propositions, tone spectrum (Dos and Don\\u2019ts), vocabulary lexicon, headline formulas, and sample copy across web, email, and social.\"},{\"q\":\"How do you discover our true brand voice?\",\"a\":\"We conduct founder interviews, analyze customer reviews, study competitor positioning gaps, and test message prototypes against your target audience.\"},{\"q\":\"Do you write the full website copy or just headlines?\",\"a\":\"We provide complete end-to-end page copy decks (Hero, features, social proof, objection teardowns, microcopy, CTAs, and metadata).\"},{\"q\":\"How many tagline options will we receive?\",\"a\":\"We typically present 15 to 20 distinct tagline concepts organized into strategic thematic angles, followed by refinement of top choices.\"},{\"q\":\"How long does a full brand messaging sprint take?\",\"a\":\"A comprehensive Brand Voice & Website Messaging deck is typically completed in 10 to 14 business days.\"}]','Ready to elevate your brand copywriting?','Tell us about your brand, goals, and upcoming requirements. We\'ll deliver a tailored proposal within 24 hours.','Start a Conversation','contact.php?service=Brand+Copywriting','brand-copy'