INSERT INTO `settings` VALUES (1,'site_name','WORDORA','2026-08-22 18:31:19'),(2,'tagline','Words That Work. Stories That Sell.','2026-08-22 18:31:19'),(3,'contact_email','info@wordora.in','2026-08-24 11:55:47'),(4,'contact_phone','+91-7023610099','2026-08-24 12:25:25'),(5,'address','Jaipur, Rajasthan, India','2026-08-24 12:25:25'),(6,'hero_mode','slider','2026-08-24 06:19:01'),(7,'hero_video_url','','2026-08-22 18:31:19'),(8,'hero_video_poster','','2026-08-23 16:35:53'),(9,'linkedin','','2026-08-22 18:31:19'),(10,'twitter','','2026-08-22 18:31:19'),(11,'instagram','','2026-08-25 00:54:47'),(21,'hero_video_active','0','2026-08-22 20:21:38'),(33,'hero_overlay_opacity','20','2026-08-24 06:56:55'),(96,'marquee_bg_image','/uploads/settings/wdr_6a8959ef922951.03270091.png','2026-08-23 17:12:31'),(230,'site_logo','/img/wordorga logo.png','2026-08-23 05:14:48'),(231,'footer_logo','/img/footer logo.png','2026-08-23 05:14:48'),(232,'home_sec2_badge','THE EDITORIAL MANDATE','2026-08-24 16:05:28'),(233,'home_sec2_title','We don\'t just write content.<br>We engineer conviction.','2026-08-24 11:36:37'),(234,'home_sec2_p1','Every piece we produce starts with deep audience research, competitive keyword intelligence, and a clear commercial thesis. The result? Words that rank, resonate, and convert not filler that fills a content calendar.','2026-08-24 11:36:37'),(235,'home_sec2_quote','Content without strategy is noise. Strategy without craft is forgettable','2026-08-24 11:36:37'),(236,'home_sec2_p2','From SEO-led topic clusters to brand manifestos and C-suite thought leadership, we bring editorial rigor and commercial intent to every sentence.','2026-08-24 11:36:37'),(237,'home_sec2_btn1_text','Explore What We Do','2026-08-24 16:05:29'),(238,'home_sec2_btn1_url','services.php','2026-08-24 16:05:29'),(239,'home_sec2_btn2_text','Read Our Story','2026-08-24 16:05:29'),(240,'home_sec2_btn2_url','who-we-are.php','2026-08-24 16:05:29'),(241,'home_sec2_artwork','/img/service treasure.png','2026-08-24 16:05:29'),(242,'home_sec2_artwork_tag','Precision Crafted','2026-08-24 16:05:29'),(243,'home_sec3_label','WHAT WE DO','2026-08-24 11:36:26'),(244,'home_sec3_title','Content with a job to do.','2026-08-24 11:36:26'),(245,'home_sec3_desc','From search-led topic clusters to C-suite thought leadership and technical documentation, we engineer words built to perform.','2026-08-24 11:36:26'),(246,'home_sec3_marquee_label','EDITORIAL CAPABILITIES','2026-08-24 11:36:26'),(247,'home_sec3_marquee_title','Content engineered for ambitious market leaders.','2026-08-24 11:36:26'),(248,'home_sec4_label','WHY BUSINESSES CHOOSE WORDORA','2026-08-24 16:05:29'),(249,'home_sec4_title','Not just writers.<br>Content thinkers & growth partners.','2026-08-24 16:05:29'),(250,'home_sec4_desc','We research before we write. We understand before we create. We build every piece around a measurable purpose — establishing industry authority, winning search intent, and converting qualified customers into long-term revenue.','2026-08-24 06:16:26'),(251,'home_sec4_quote','“Good content fills a page. Great content moves someone.”','2026-08-24 06:16:26'),(252,'home_sec4_btn_text','Read Our Story','2026-08-24 16:05:29'),(253,'home_sec4_btn_url','who-we-are.php','2026-08-24 16:05:29'),(254,'home_sec4_artwork','/img/why choose us.png','2026-08-24 16:05:29'),(255,'home_sec4_cards','[{\"icon\":\"ri-quill-pen-line\",\"title\":\"100% Human Craftsmanship\",\"desc\":\"No generic AI-generated filler. Every piece is written, refined, and polished by seasoned industry writers with real editorial voice.\"},{\"icon\":\"ri-search-eye-line\",\"title\":\"Intent-First SEO Strategy\",\"desc\":\"We map topic clusters and search intent so your content outranks competition and captures buyers at every evaluation stage.\"},{\"icon\":\"ri-funds-box-line\",\"title\":\"Conversion-Focused Copy\",\"desc\":\"Landing pages, pitch decks, and brand taglines engineered to clearly communicate value and lift conversion rates.\"},{\"icon\":\"ri-shield-check-line\",\"title\":\"Obsessive Fact-Checking\",\"desc\":\"Every statistic, citation, and technical term is double-verified to protect your brand\'s market reputation and credibility.\"},{\"icon\":\"ri-timer-flash-line\",\"title\":\"Predictable Turnaround\",\"desc\":\"Strict sprint milestones, transparent project updates, and two full rounds of baked-in revisions on every single delivery.\"},{\"icon\":\"ri-bookmark-3-line\",\"title\":\"Style Guide & Tone Governance\",\"desc\":\"We create and follow bespoke editorial guidelines so your brand speaks with one unified, authoritative, and recognizable tone.\"}]','2026-08-24 16:05:29'),(256,'home_sec4_stats','[{\"count\":\"1000\",\"suffix\":\"+\",\"label\":\"Projects Delivered\"},{\"count\":\"170\",\"suffix\":\"+\",\"label\":\"Happy Clients\"},{\"count\":\"8\",\"suffix\":\"+\",\"label\":\"Years Experience\"},{\"count\":\"98\",\"suffix\":\"%\",\"label\":\"Client Retention\"}]','2026-08-24 16:05:29'),(257,'home_sec5_label','WHO WE WRITE FOR','2026-08-24 16:05:29'),(258,'home_sec5_title','Different industries.<br>One obsession: clarity.','2026-08-24 16:05:29'),(259,'home_sec5_desc','Content changes with the audience. Our thinking changes with it. We adapt tone, technical depth, and vocabulary to the exact expectations of your market.','2026-08-24 16:05:29'),(260,'home_sec5_artwork','/img/industry.png','2026-08-24 16:05:29'),(261,'home_sec5_slides','[{\"badge\":\"Verified Deliverable — SaaS & DevOps\",\"title\":\"ScaleStack Cloud: Engineering Developer Trust & Technical Authority\",\"desc\":\"Architected a 24-part deep-technical whitepaper series and interactive API documentation suite that simplified multi-cloud Kubernetes orchestration for enterprise CTOs and technical engineering leads.\",\"m1_val\":\"1000+\",\"m1_lbl\":\"Projects Delivered\",\"m2_val\":\"+420%\",\"m2_lbl\":\"Developer Signups\",\"btn1_text\":\"Request Similar Project Scope\",\"btn1_url\":\"contact.php\",\"btn2_text\":\"View SaaS Services\",\"btn2_url\":\"services.php#technical-writing\",\"media_tag\":\"Client Success Study\",\"img\":\"\\/img\\/case study.png\"},{\"badge\":\"Verified Deliverable — Banking & Payments\",\"title\":\"NovaPay Global: Demystifying Cross-Border Settlement & API Rails\",\"desc\":\"Crafted institutional compliance narratives, enterprise security whitepapers, and merchant onboarding guides that established unshakeable credibility across 40+ international markets.\",\"m1_val\":\"170+\",\"m1_lbl\":\"Happy Clients\",\"m2_val\":\"₹1.2B+\",\"m2_lbl\":\"Annual Volume Scaled\",\"btn1_text\":\"Request Similar Project Scope\",\"btn1_url\":\"contact.php\",\"btn2_text\":\"View FinTech Services\",\"btn2_url\":\"services.php#brand-copy\",\"media_tag\":\"Client Success Study\",\"img\":\"\\/img\\/client.png\"},{\"badge\":\"Verified Deliverable — D2C & Retail\",\"title\":\"Aura Living: Editorial Product Storytelling for Luxury Goods\",\"desc\":\"Authored immersive collection lookbooks, persuasive high-AOV product copy, and a 12-stage automated customer nurture sequence that drove immediate repeat purchases and high loyalty.\",\"m1_val\":\"98%\",\"m1_lbl\":\"Client Retention Rate\",\"m2_val\":\"+3.2x\",\"m2_lbl\":\"Email Revenue Scaled\",\"btn1_text\":\"Request Similar Project Scope\",\"btn1_url\":\"contact.php\",\"btn2_text\":\"View D2C Services\",\"btn2_url\":\"services.php#email-marketing\",\"media_tag\":\"Client Success Study\",\"img\":\"\\/img\\/case study.png\"},{\"badge\":\"Verified Deliverable — Early & Growth Stage\",\"title\":\"HyperVenture AI: Crafting the Seed Manifesto & Founding Story\",\"desc\":\"Transformed complex generative AI model architecture into an irresistible investor deck narrative, founding manifesto, and launch press release that captivated Silicon Valley venture funds.\",\"m1_val\":\"8+\",\"m1_lbl\":\"Years Experience\",\"m2_val\":\"₹4.8M\",\"m2_lbl\":\"Seed Round Secured\",\"btn1_text\":\"Request Similar Project Scope\",\"btn1_url\":\"contact.php\",\"btn2_text\":\"View Startup Services\",\"btn2_url\":\"services.php#brand-copy\",\"media_tag\":\"Client Success Study\",\"img\":\"\\/img\\/client.png\"},{\"badge\":\"Verified Deliverable — MedTech & Wellness\",\"title\":\"CarePulse Health: Clinical Precision Meets Patient Empathy\",\"desc\":\"Produced rigorous medical review articles and patient-facing symptom triage guides, establishing certified domain authority and winning zero-click Google featured snippets.\",\"m1_val\":\"1000+\",\"m1_lbl\":\"Projects Delivered\",\"m2_val\":\"+210%\",\"m2_lbl\":\"Patient Consultations\",\"btn1_text\":\"Request Similar Project Scope\",\"btn1_url\":\"contact.php\",\"btn2_text\":\"View Health Services\",\"btn2_url\":\"services.php#seo-content\",\"media_tag\":\"Client Success Study\",\"img\":\"\\/img\\/case study.png\"},{\"badge\":\"Verified Deliverable — AI & Infrastructure\",\"title\":\"TensorVector: Open-Source Documentation & Enterprise Funnels\",\"desc\":\"Built developer documentation, quickstart tutorials, and enterprise comparison benchmarks that drove developer adoption from GitHub to paid enterprise cloud contracts.\",\"m1_val\":\"170+\",\"m1_lbl\":\"Happy Clients\",\"m2_val\":\"15k+\",\"m2_lbl\":\"GitHub Repository Stars\",\"btn1_text\":\"Request Similar Project Scope\",\"btn1_url\":\"contact.php\",\"btn2_text\":\"View Tech Services\",\"btn2_url\":\"services.php#technical-writing\",\"media_tag\":\"Client Success Study\",\"img\":\"\\/img\\/client.png\"},{\"badge\":\"Verified Deliverable — EdTech & Platforms\",\"title\":\"Cognito Academy: Curriculum Storytelling & Student Acquisition\",\"desc\":\"Structured authoritative course landing pages, student success study essays, and masterclass email campaigns across 12 professional disciplines with exceptional enrollment rates.\",\"m1_val\":\"98%\",\"m1_lbl\":\"Client Retention Rate\",\"m2_val\":\"85k+\",\"m2_lbl\":\"Enrolled Students\",\"btn1_text\":\"Request Similar Project Scope\",\"btn1_url\":\"contact.php\",\"btn2_text\":\"View EdTech Services\",\"btn2_url\":\"services.php#content-strategy\",\"media_tag\":\"Client Success Study\",\"img\":\"\\/img\\/case study.png\"},{\"badge\":\"Verified Deliverable — B2B & Consulting\",\"title\":\"Vanguard Advisory: C-Suite Thought Leadership on LinkedIn\",\"desc\":\"Ghostwrote weekly strategic essays and annual industry research reports for managing partners, driving direct inbound consulting requests from Fortune 500 leadership.\",\"m1_val\":\"8+\",\"m1_lbl\":\"Years Experience\",\"m2_val\":\"+540%\",\"m2_lbl\":\"Inbound Executive Leads\",\"btn1_text\":\"Request Similar Project Scope\",\"btn1_url\":\"contact.php\",\"btn2_text\":\"View B2B Services\",\"btn2_url\":\"services.php#social-media\",\"media_tag\":\"Client Success Study\",\"img\":\"\\/img\\/client.png\"}]','2026-08-25 06:08:22'),(262,'home_sec6_label','OUR PROCESS','2026-08-24 16:05:29'),(263,'home_sec6_title','From brief to brilliance.','2026-08-24 16:05:29'),(264,'home_sec6_desc','Every project follows a clear editorial rhythm — research first, strategy next, craft throughout.','2026-08-24 06:16:26'),(265,'home_sec6_artwork','/img/process.png','2026-08-24 16:05:29'),(266,'home_sec6_flow_tag','Research  →  Strategy  →  Writing  →  Refinement','2026-08-24 06:16:41'),(267,'home_sec6_steps','[{\"step_num\":\"STEP 01\",\"title\":\"Discovery & Context Gathering\",\"desc\":\"We learn your brand, audience, goals, and competitive landscape inside-out before a single sentence is typed.\"},{\"step_num\":\"STEP 02\",\"title\":\"Editorial Strategy & Outlining\",\"desc\":\"We turn insights into a structured outline built around what your audience searches for, needs, and remembers.\"},{\"step_num\":\"STEP 03\",\"title\":\"Human Craft & Drafting\",\"desc\":\"Specialist writers shape raw ideas into sharp, engaging, SEO-optimized, and distinctly human content.\"},{\"step_num\":\"STEP 04\",\"title\":\"Polishing & Final Delivery\",\"desc\":\"Thoroughly fact-checked, SEO-formatted, and delivered on schedule — with two rounds of revisions baked in.\"}]','2026-08-24 06:16:26'),(268,'home_sec7_label','CLIENT STORIES','2026-08-24 16:05:29'),(269,'home_sec7_title','“The work speaks too.”','2026-08-24 06:16:26'),(270,'home_sec7_testimonials','[{\"quote\":\"WORDORA transformed our content from something we routinely published into something our audience actively looked forward to reading. Organic traffic increased 4x in 6 months, and our inbound pipeline has never been healthier.\",\"author_name\":\"Priya Sharma\",\"author_role\":\"Founder & CEO, TechGrowth India\",\"author_badge\":\"Verified Client — SaaS & FinTech\",\"initials\":\"PS\",\"avatar_bg\":\"var(--color-navy)\",\"avatar_img\":\"\",\"stars\":5},{\"quote\":\"Their brand copywriting gave us the voice we had been searching for. Every tagline, pitch deck, and landing page now sounds distinct, credible, and relentlessly conversion-focused.\",\"author_name\":\"Rahul Verma\",\"author_role\":\"Chief Marketing Officer, NovaBrands\",\"author_badge\":\"Verified Client — D2C & Retail\",\"initials\":\"RV\",\"avatar_bg\":\"var(--color-navy)\",\"avatar_img\":\"\",\"stars\":5},{\"quote\":\"Working with WORDORA feels like having an in-house elite editorial board. They understand complex B2B tech nuance and consistently deliver publish-ready whitepapers on schedule.\",\"author_name\":\"Ananya Singh\",\"author_role\":\"Content Lead, SaaS Studio\",\"author_badge\":\"Verified Client — Enterprise Cloud\",\"initials\":\"AS\",\"avatar_bg\":\"var(--color-navy)\",\"avatar_img\":\"\",\"stars\":5}]','2026-08-25 05:48:47'),(271,'home_sec7_metrics','[{\"num\":\"+4x\",\"label\":\"Organic Search Traffic\"},{\"num\":\"+68%\",\"label\":\"Reader Engagement\"},{\"num\":\"5x\",\"label\":\"Content Production Velocity\"},{\"num\":\"98%\",\"label\":\"Client Retention Rate\"}]','2026-08-25 05:48:47'),(272,'home_sec8_label','FROM THE EDITORIAL DESK','2026-08-24 16:05:29'),(273,'home_sec8_title','Ideas worth reading.','2026-08-24 16:05:29'),(274,'home_sec8_btn_text','View All Insights','2026-08-24 16:05:29'),(275,'home_sec8_btn_url','blog/','2026-08-24 16:05:29'),(276,'home_sec8_count','3','2026-08-24 16:05:29'),(277,'home_sec9_badge','LET\'S MAKE SOMETHING MEANINGFUL','2026-08-24 16:05:29'),(278,'home_sec9_title','Start something <em>worth reading.</em>','2026-08-24 16:05:29'),(279,'home_sec9_desc','Tell us what you\'re building. We\'ll help you find the words to move it forward, engage the right audience, and drive sustainable pipeline growth.','2026-08-24 16:05:29'),(280,'home_sec9_btn1_text','Start a Conversation','2026-08-24 16:05:29'),(281,'home_sec9_btn1_url','contact.php','2026-08-24 16:05:29'),(282,'home_sec9_btn2_text','Explore Studio','2026-08-24 16:05:29'),(283,'home_sec9_btn2_url','who-we-are.php','2026-08-24 16:05:29'),(284,'home_sec9_pill1','24h Response','2026-08-24 16:05:29'),(285,'home_sec9_pill2','NDA Protected','2026-08-24 16:05:29'),(286,'home_sec9_pill3','Free Content Audit','2026-08-24 16:05:29'),(287,'home_sec9_artwork','/uploads/home/wdr_6a8d6876e09271.98972750.png','2026-08-25 04:33:34'),(288,'home_sec3_bento','[{\"badge\":\"High Impact & SearchTEST\",\"icon\":\"\",\"title\":\"SEO Content Writing\",\"desc\":\"Deeply researched articles, search-intent blog posts, and authoritative guides that outrank generic competitor copy and satisfy real humans.\",\"tags\":\"Topic Cluster Frameworks, Keyword Intent Optimization, Long-Form SEO Content\",\"btn_text\":\"Explore SEO Writing\",\"btn_url\":\"service\\/seo-content-writing\",\"btn2_text\":\"\",\"btn2_url\":\"\"},{\"badge\":\"Voice & Positioning\",\"icon\":\"\",\"title\":\"Brand Copywriting\",\"desc\":\"Taglines, manifestos, about pages, and messaging architectures that give ambitious brands an unmistakable, authoritative tone.\",\"tags\":\"\",\"btn_text\":\"Craft Brand Voice\",\"btn_url\":\"service\\/brand-copy\",\"btn2_text\":\"\",\"btn2_url\":\"\"},{\"badge\":\"Publishing & Insights\",\"icon\":\"\",\"title\":\"Blog & Article Writing\",\"desc\":\"Compelling editorial essays, Quora answers, company profiles, and regular publication series that build trusted reader followings.\",\"tags\":\"\",\"btn_text\":\"Explore Blog Writing\",\"btn_url\":\"service\\/blog-writing\",\"btn2_text\":\"\",\"btn2_url\":\"\"},{\"badge\":\"Scholarly Rigor\",\"icon\":\"\",\"title\":\"Academic & Research Writing\",\"desc\":\"Peer-reviewed syntheses, dissertations, research papers, and scholarly reports fact-checked to institutional standards.\",\"tags\":\"\",\"btn_text\":\"Explore Research Writing\",\"btn_url\":\"service\\/academic-writing\",\"btn2_text\":\"\",\"btn2_url\":\"\"},{\"badge\":\"Clarity & Docs\",\"icon\":\"\",\"title\":\"Technical Writing\",\"desc\":\"Translating complex software architectures, developer APIs, and cloud infrastructure into readable documentation.\",\"tags\":\"\",\"btn_text\":\"Explore Technical Docs\",\"btn_url\":\"service\\/technical-writing\",\"btn2_text\":\"\",\"btn2_url\":\"\"},{\"badge\":\"Executive & Founder Authority\",\"icon\":\"\",\"title\":\"Thought Leadership & Executive Voice\",\"desc\":\"Ghostwritten C-suite LinkedIn essays, founder personal branding, and multi-channel executive communication that establish undeniable industry authority.\",\"tags\":\"\",\"btn_text\":\"Explore Thought Leadership\",\"btn_url\":\"service\\/thought-leadership\",\"btn2_text\":\"View All 7 Disciplines\",\"btn2_url\":\"services\"}]','2026-09-05 04:10:15'),(289,'home_sec3_marquee_rows','{\"row1\":\"SEO Content Writing, Brand Voice Architecture, Thought Leadership Essays, Social Editorial Calendars, Email Sequences & Newsletters, Technical Whitepapers, Full-Funnel Content Strategy\",\"row2\":\"Conversion Copywriting, Case Study Narratives, Topic Cluster Frameworks, Enterprise B2B Whitepapers, Fact-Checked Research, Executive Ghostwriting, Content Audits & Roadmaps\",\"row3\":\"Keyword Intent Mapping, Long-Form Authority Guides, High-Converting Pitch Decks, Onboarding Email Sequences, Industry Authority Benchmarks, Viral LinkedIn Carousels, Multi-Format Repurposing\"}','2026-08-24 10:44:14'),(324,'who_sec1_badge','EDITORIAL BRAND STORY & STUDIO MANIFESTO','2026-08-24 05:35:00'),(325,'who_sec1_title','Who We Are','2026-08-24 05:35:00'),(326,'who_sec1_desc','A team of writers, strategists, and editors driven by the belief that great words build great brands.','2026-08-24 05:35:00'),(327,'who_sec1_btn1_text','Explore Our Story','2026-08-24 05:35:00'),(328,'who_sec1_btn1_url','#our-mission','2026-08-24 05:35:00'),(329,'who_sec1_btn2_text','Start a Conversation','2026-08-24 05:35:00'),(330,'who_sec1_btn2_url','contact.php','2026-08-24 05:35:00'),(331,'who_sec2_badge','OUR MISSION','2026-08-24 05:35:00'),(332,'who_sec2_title','We believe words<br>shape worlds.','2026-08-24 05:35:00'),(333,'who_sec2_p1','WORDORA was founded on a simple truth: the right words, at the right moment, can transform a brand. We don\'t just create content — we craft narratives that connect, captivate, persuade, and leave a lasting impression.','2026-08-24 05:35:00'),(334,'who_sec2_quote','“Good content fills a page. Great content moves someone.”','2026-08-24 05:35:00'),(335,'who_sec2_p2','From our base in Agra to brands across India and beyond, we\'ve evolved from a two-person editorial team into a full-service content agency trusted by 170+ brands across SaaS, E-commerce, FinTech, Education, Gaming, and more.','2026-08-24 05:35:00'),(336,'who_sec2_btn1_text','Read Our Journey','2026-08-24 05:35:00'),(337,'who_sec2_btn1_url','#journey','2026-08-24 05:35:00'),(338,'who_sec2_btn2_text','Explore Services','2026-08-24 05:35:00'),(339,'who_sec2_btn2_url','services.php','2026-08-24 05:35:00'),(340,'who_sec2_artwork','/img/why choose us.png','2026-08-24 05:35:00'),(341,'who_sec3_badge','EDITORIAL CAPABILITIES','2026-08-24 05:35:00'),(342,'who_sec3_title','Content engineered for ambitious market leaders.','2026-08-24 05:35:00'),(343,'who_sec3_marquee_bg','/img/papaer banner.png','2026-08-24 05:35:00'),(344,'who_sec3_rows','{\"row1\":\"SEO Content Writing, Brand Voice Architecture, Thought Leadership Essays, Social Editorial Calendars, Email Sequences & Newsletters, Technical Whitepapers, Full-Funnel Content Strategy\",\"row2\":\"Conversion Copywriting, Case Study Narratives, Topic Cluster Frameworks, Enterprise B2B Whitepapers, Fact-Checked Research, Executive Ghostwriting, Content Audits & Roadmaps\",\"row3\":\"Keyword Intent Mapping, Long-Form Authority Guides, High-Converting Pitch Decks, Onboarding Email Sequences, Industry Authority Benchmarks, Viral LinkedIn Carousels, Multi-Format Repurposing\"}','2026-08-24 05:35:00'),(345,'who_sec4_badge','OUR JOURNEY','2026-08-24 05:35:00'),(346,'who_sec4_title','Words got us started.<br>Ideas took us further.','2026-08-24 05:35:00'),(347,'who_sec4_desc','What began as a small writing studio in Agra slowly became a place where brands come to find their voice, sharpen their story, and say something worth remembering.','2026-08-24 05:35:00'),(348,'who_sec4_artwork','/img/journey.png','2026-08-24 05:35:00'),(349,'who_sec4_milestones','[{\"year\":\"2018\",\"tag\":\"2018 — THE FIRST SENTENCE\",\"title\":\"A desk in Jaipur.\",\"desc\":\"A desk in Jaipur. A freelance studio. And one stubborn belief exceptional words could build exceptional brands.\",\"is_active\":false},{\"year\":\"2020\",\"tag\":\"2020 — THE STORY TRAVELS\",\"title\":\"From one city to a country-wide journey.\",\"desc\":\"From one city to a country-wide journey. 50+ clients, a growing team, and stories travelling far beyond our first desk.\",\"is_active\":false},{\"year\":\"2022\",\"tag\":\"2022 — FINDING NEW VOICES\",\"title\":\"We stepped beyond the page.\",\"desc\":\"We stepped beyond the page — building dedicated SEO and social content capabilities to help brands get found, followed, and remembered.\",\"is_active\":false},{\"year\":\"2024\",\"tag\":\"2024 — 500+ STORIES LATER\",\"title\":\"500+ Opportunities to think differently.\",\"desc\":\"Our 500th project wasn\'t just a milestone. It was 500+ opportunities to think differently, tell better stories, and earn trust along the way.\",\"is_active\":false},{\"year\":\"2026\",\"tag\":\"2026 — THE NEXT SENTENCE IS OURS TO WRITE\",\"title\":\"Carrying our craft into a bigger chapter.\",\"desc\":\"Now, we\'re moving beyond content into strategy, consulting, and enterprise partnerships  carrying everything we\'ve learned into a much bigger chapter.\",\"is_active\":true}]','2026-08-25 05:16:31'),(350,'who_sec5_badge','OUR CORE VALUES','2026-08-24 05:35:00'),(351,'who_sec5_title','What Guides Every Word We Write.','2026-08-24 05:35:00'),(352,'who_sec5_desc','Three foundational editorial principles that shape how we think, write, and deliver impact for every partner brand.','2026-08-24 05:35:00'),(353,'who_sec5_artwork','/img/value.png','2026-08-24 05:35:00'),(354,'who_sec5_cards','[{\"num\":\"01 \\/ DISCIPLINE\",\"icon\":\"ri-quill-pen-line\",\"title\":\"Craft Over Commodity\",\"desc\":\"Every sentence is deliberate. We treat writing as an editorial discipline, not generic filler or AI commodity text.\"},{\"num\":\"02 \\/ STRUCTURE\",\"icon\":\"ri-lightbulb-line\",\"title\":\"Radical Clarity\",\"desc\":\"Complex software and industry ideas deserve clean expression. We cut through noise to deliver pure substance and hook reader attention.\"},{\"num\":\"03 \\/ OUTCOME\",\"icon\":\"ri-line-chart-line\",\"title\":\"Conversion-Driven Impact\",\"desc\":\"Beautiful writing that doesn\'t convert is just decoration. We align every story with tangible search growth and business pipeline.\"}]','2026-08-24 05:35:00'),(355,'who_sec6_badge','MEET THE TEAM','2026-08-24 05:35:00'),(356,'who_sec6_title','The People Behind the Words','2026-08-24 05:35:00'),(357,'who_sec6_desc','Writers. Strategists. Editors. Each one obsessed with research, editorial rhythm, and doing the work right.','2026-08-24 05:35:00'),(358,'who_sec6_team','[{\"name\":\"Priya Sharma\",\"role\":\"Founder & Head of Strategy\",\"spec\":\